package org.sleepwell.app;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Immutable vendor source evidence in the same database/transaction as its imported period.
 * Root schema/backup integration calls these helpers; no external receipt database is used. */
final class SleepCsvEvidence {
    static final int MAX_BYTES=3*1024*1024,MAX_PORTABLE=4*1024*1024;
    static void createTables(SQLiteDatabase db){db.execSQL("CREATE TABLE sleep_csv_sources(session INTEGER PRIMARY KEY,source_id TEXT UNIQUE NOT NULL,sha256 TEXT NOT NULL,csv TEXT NOT NULL)");db.execSQL("CREATE TRIGGER delete_sleep_csv_source AFTER DELETE ON sessions BEGIN DELETE FROM sleep_csv_sources WHERE session=OLD.id; END");}
    static JSONObject export(Store store)throws JSONException {JSONArray rows=new JSONArray();long bytes=0;for(JSONObject row:store.rows("SELECT session,source_id,sha256,csv FROM sleep_csv_sources ORDER BY session")){bytes+=row.getString("csv").getBytes(StandardCharsets.UTF_8).length;if(bytes>MAX_BYTES||rows.length()>=SleepCsvFormat.MAX_RECORDS)throw new JSONException("Imported CSV evidence exceeds the supported portable limit.");rows.put(row);}JSONObject payload=new JSONObject().put("version",1).put("records",rows);if(payload.toString().getBytes(StandardCharsets.UTF_8).length>MAX_PORTABLE)throw new JSONException("Imported CSV evidence exceeds the 4 MiB portable limit.");return payload;}
    static void validate(JSONObject payload,Map<Long,JSONObject> sessions)throws JSONException {if(payload==null)return;try{
        if(payload.length()!=2||whole(payload,"version")!=1||!(payload.get("records") instanceof JSONArray)||payload.toString().getBytes(StandardCharsets.UTF_8).length>MAX_PORTABLE)throw new IllegalArgumentException("Unsupported imported CSV evidence.");JSONArray rows=payload.getJSONArray("records");if(rows.length()>SleepCsvFormat.MAX_RECORDS)throw new IllegalArgumentException("Too many imported CSV records.");Set<Long> ids=new HashSet<>();Set<String> sources=new HashSet<>();long bytes=0;
        for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.length()!=4)throw new IllegalArgumentException("Unexpected imported CSV fields.");long id=whole(row,"session");String source=text(row,"source_id"),sha=text(row,"sha256"),csv=text(row,"csv");bytes+=csv.getBytes(StandardCharsets.UTF_8).length;if(id<=0||!ids.add(id)||!sources.add(source)||!sha.matches("[0-9a-f]{64}")||bytes>MAX_BYTES)throw new IllegalArgumentException("Invalid imported CSV identity or size.");SleepCsvFormat.Entry entry=SleepCsvFormat.one(csv);JSONObject session=sessions.get(id);if(!entry.sourceId.equals(source)||!entry.sha256.equals(sha)||session==null||session.isNull("end")||whole(session,"start")!=entry.start||whole(session,"end")!=entry.end||!"manual".equals(session.optString("source"))||!"imported".equals(session.optString("origin"))||!entry.zone.equals(session.optString("zone"))||!"none".equals(session.optString("sensor"))||!session.isNull("active_ms"))throw new IllegalArgumentException("Imported CSV evidence disagrees with its original period.");}
    }catch(Exception invalid){if(invalid instanceof JSONException)throw (JSONException)invalid;throw new JSONException(invalid.getMessage()==null?"Invalid imported CSV evidence.":invalid.getMessage());}}
    static void replace(Store store,JSONObject payload)throws JSONException {Map<Long,JSONObject> sessions=new HashMap<>();for(JSONObject row:store.rows("SELECT * FROM sessions"))sessions.put(row.optLong("id"),row);validate(payload,sessions);SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{db.delete("sleep_csv_sources",null,null);if(payload!=null){JSONArray rows=payload.getJSONArray("records");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);ContentValues values=new ContentValues();values.put("session",whole(row,"session"));values.put("source_id",text(row,"source_id"));values.put("sha256",text(row,"sha256"));values.put("csv",text(row,"csv"));db.insertOrThrow("sleep_csv_sources",null,values);}}db.setTransactionSuccessful();}finally{db.endTransaction();}}
    static SleepCsvFormat.Entry get(Store store,long session){List<JSONObject> rows=store.rows("SELECT csv FROM sleep_csv_sources WHERE session=?",""+session);if(rows.isEmpty())return null;try{return SleepCsvFormat.one(rows.get(0).getString("csv"));}catch(Exception unreadable){throw new IllegalStateException("The imported source evidence is unavailable.",unreadable);}}
    static String summary(Store store,long session){return store.rows("SELECT source_id FROM sleep_csv_sources WHERE session=?",""+session).isEmpty()?"":"Sleep as Android CSV · imported period";}
    static String detail(Store store,long session){SleepCsvFormat.Entry e=get(store,session);if(e==null)return "No Sleep as Android CSV source evidence is attached to this record.";return "Sleep as Android CSV import\nSource ID: "+e.sourceId+"\nSource zone: "+e.zone+"\nOriginal period: "+RecordUi.date(e.start,java.time.ZoneId.of(e.zone))+" · "+java.time.Instant.ofEpochMilli(e.start)+" to "+java.time.Instant.ofEpochMilli(e.end)+"\nPeriod duration: "+RecordUi.duration(e.period)+"\nVendor LenAdjust: "+(e.adjustmentMinutes==null?"not reported for this manual source":e.adjustmentMinutes+" min")+"\nVendor adjusted duration: "+(e.netDuration==null?"not reported":RecordUi.duration(e.netDuration))+"\nOriginal rating: "+e.rating.toPlainString()+" / 5"+(e.fractionalRating()?" (kept here; SleepWell's integer rating was left unset)":"")+"\nActigraphy values retained: "+e.actigraphy+"\nNoise values retained: "+e.noise+"\nEvent values retained: "+e.events+(e.dstResolved?"\nRepeated local times were resolved using the source Id and Hours.":"")+"\n\nThe app duration is the imported period, not the vendor's adjusted sleep estimate. Aggregate awake adjustment has no known placement and does not become awake spans. Vendor movement/noise scales and stage events are retained as source data, not SleepWell measurements. Original alarm schedule, location hash and other CSV fields remain in the source rows only; no alarms or sensor data were created.";}
    static void add(Store store,long session,SleepCsvFormat.Entry entry){ContentValues row=new ContentValues();row.put("session",session);row.put("source_id",entry.sourceId);row.put("sha256",entry.sha256);row.put("csv",entry.raw);store.getWritableDatabase().insertOrThrow("sleep_csv_sources",null,row);}
    static long bytes(Store store){try(Cursor result=store.getReadableDatabase().rawQuery("SELECT COALESCE(SUM(length(CAST(csv AS BLOB))),0) FROM sleep_csv_sources",null)){return result.moveToFirst()?result.getLong(0):0;}}
    private static long whole(JSONObject row,String key)throws JSONException{Object raw=row.get(key);if(!(raw instanceof Number)||!Double.isFinite(((Number)raw).doubleValue())||((Number)raw).doubleValue()!=((Number)raw).longValue()||Math.abs(((Number)raw).doubleValue())>9007199254740991d)throw new JSONException("Invalid CSV evidence integer.");return ((Number)raw).longValue();}
    private static String text(JSONObject row,String key)throws JSONException{Object value=row.get(key);if(!(value instanceof String))throw new JSONException("Invalid CSV evidence text.");return (String)value;}
    private SleepCsvEvidence(){}
}
